const input = $input.first().json;
const phase = input.phase;
if (!['build_probe', 'locate_precise_time'].includes(phase)) throw new Error('Unsupported phase');
let prompt;
if (phase === 'build_probe') {
  const required = ['country', 'source_sql', 'comparison_sql', 'data_date'];
  const missing = required.filter((key) => !input[key]);
  if (missing.length) throw new Error(`Missing required fields: ${missing.join(', ')}`);
  prompt = `You are a data-quality analyst. Build a measurement plan only; do not execute SQL. Based exclusively on source_sql and comparison_sql below, return JSON with source_probe_sql, comparison_probe_sql, bucket_granularity, rationale. Each SQL must be exactly one read-only SELECT/WITH aggregate using only the table(s) already present in its corresponding original SQL, preserve a bounded time predicate within the original time interval, aggregate by the original time field, and return at most 400 time buckets. Do not use semicolons, DDL, DML, comments, or any new table. Use COUNT or the same aggregate as the original metric.\n\nInput:\n${JSON.stringify(input)}`;
} else {
  prompt = `You are a data-quality analyst. Determine the precise first anomalous business timestamp using only the two SRBox read-only aggregate results below. Do not execute SQL and do not invent data. Return JSON only with precise_anomaly_time (YYYY-MM-DD or YYYY-MM-DD HH:MM:SS, or null), confidence, reasoning, evidence_needed. If the probe does not establish a first time, return null.\n\nInput:\n${JSON.stringify(input)}`;
}
return [{ json: { input, prompt } }];

